/* Original local projects informed by public Togolese training catalogues. */
state.localProjects=state.localProjects||{};
for(const s of SECTORS){for(const j of s.jobs){if(s.id==='health'&&!j.path.includes('information-sante'))j.path.push('information-sante');if(['business','logistics','education','construction'].includes(s.id)&&!j.path.includes('bureautique'))j.path.push('bureautique')}}
SECTORS.find(s=>s.id==='agri').jobs.push({name:'Aquaculteur / aquacultrice',intro:'Découvrir les informations, les mesures et la gestion d’une filière aquacole, puis poursuivre une formation pratique.',path:['aquaculture','biology','bureautique','agro-projet'],next:'Le site de l’AED décrit une filière IFAD en aquaculture. Vérifier directement les conditions actualisées ; ce parcours Nunya n’est pas une qualification.'});
SECTORS.find(s=>s.id==='construction').jobs.push({name:'Technicien / technicienne du froid',intro:'Explorer les bases de physique, les mesures et l’organisation des interventions, avant une formation professionnelle encadrée.',path:['physics','construction','bureautique','gestion-projet'],next:'L’AED présente une filière Froid et conditionnement de l’air. La pratique exige une formation et un encadrement adaptés ; aucune manipulation réelle n’est demandée ici.'});
let projectData=null,platformData=null,projectDataPromise=null,currentProject=null;
function loadProjects(){if(projectData)return Promise.resolve();if(projectDataPromise)return projectDataPromise;projectDataPromise=Promise.all([readJson('./data/togo_projects.json'),readJson('./data/togo_platforms.json')]).then(([p,s])=>{projectData=p;platformData=s}).finally(()=>{projectDataPromise=null});return projectDataPromise}
function projectPanel(s){return `<section class="project-invite"><div><span class="eyebrow">APPRENDRE EN FAISANT · 20 À 40 MINUTES</span><h2>Un premier projet en ${esc(s.short.toLowerCase())}.</h2><p>Une mission, des étapes, un petit livrable. Garde ton brouillon et observe ce que tu sais faire.</p></div><button class="primary" data-local-project="${s.id}">Créer mon projet →</button></section>`}
const sectorBeforeProjects=sectorView;sectorView=function(s){let html=sectorBeforeProjects(s);html=html.replace('</section>','</section>'+projectPanel(s));const local=(platformData||[]).filter(p=>p.sectors.includes(s.id));if(local.length)html+=`<section class="panel local-platforms"><span class="eyebrow">REPÈRES AU TOGO</span><h3>Des façons d’apprendre qui nous inspirent.</h3>${local.map(p=>`<details><summary>${esc(p.name)}</summary><p>${esc(p.finding)}</p><p><strong>Dans Nunya :</strong> ${esc(p.implemented)}</p><small>${esc(p.access)}</small><a href="${esc(p.url)}" target="_blank" rel="noopener">Source consultée le ${p.last_checked} ↗</a></details>`).join('')}<p class="profile-line">Analyse et activités originales Nunya. Aucun partenariat ni accès aux cours fermés n’est revendiqué.</p></section>`;else if(!platformData)queueMicrotask(()=>loadProjects().then(()=>{if(page==='careers'&&$('#modal').hidden)render()}).catch(()=>{}));return html};
const progressBeforeProjects=progressView;progressView=function(){let html=progressBeforeProjects();const saved=Object.entries(state.localProjects);html+=`<section class="panel my-projects"><span class="eyebrow">CE QUE JE CONSTRUIS</span><h3>Mon portfolio de projets <span>${saved.length}</span></h3><p>Des brouillons locaux, des idées et des réalisations que tu peux améliorer. Les cases cochées sont ton auto-évaluation, pas une validation professionnelle.</p>${saved.length?saved.map(([id,p])=>`<div class="saved-row"><button data-local-project="${id}">${esc(p.title||'Mon projet')} →</button><small>${(p.tasks||[]).filter(Boolean).length} étapes cochées · ${esc((p.updatedAt||'').slice(0,10))}</small></div>`).join(''):'<p>Dans Mon avenir, choisis un domaine puis « Créer mon projet ».</p>'}<button class="secondary" data-page="careers">Trouver mon prochain projet →</button></section>`;return html};
async function openProject(id){try{await loadProjects();const t=projectData.find(p=>p.id===id);if(!t)return;stopRuntime();currentProject=t;const p=state.localProjects[id]||{},budget=p.budget||{};modal(`<span class="eyebrow">MON PROJET · ${esc(SECTORS.find(s=>s.id===id)?.short||'')}</span><h2 id="modal-title">${esc(t.title)}</h2><p>${esc(t.mission)}</p><form id="local-project-form"><label class="field">Le nom de mon projet<input name="title" maxlength="100" value="${esc(p.title||t.title)}" required></label><section class="project-steps"><h3>Mes trois étapes</h3>${t.tasks.map((task,i)=>`<label><input type="checkbox" name="task-${i}" ${p.tasks?.[i]?'checked':''}><span>${i+1}. ${esc(task)}</span></label>`).join('')}</section><p class="project-deliverable"><strong>Ce que je prépare :</strong> ${esc(t.deliverable)}</p><label class="field">Mon idée / mon raisonnement<textarea name="idea" rows="4" maxlength="3000">${esc(p.idea||'')}</textarea></label><label class="field">Ce que j’observe ou ce que je dois vérifier<textarea name="observations" rows="3" maxlength="3000">${esc(p.observations||'')}</textarea></label><details class="project-budget"><summary>Tester un budget fictif en FCFA</summary><p>Une simulation simple de recette et de coût. Ce résultat ne représente pas la viabilité d’une activité réelle.</p><div class="project-budget-fields"><label>Quantité<input id="project-quantity" name="quantity" type="number" min="0" max="100000" step="1" value="${budget.quantity??10}"></label><label>Prix unitaire fictif<input id="project-price" name="price" type="number" min="0" max="100000000" value="${budget.price??500}"></label><label>Coûts totaux fictifs<input id="project-costs" name="costs" type="number" min="0" max="100000000" value="${budget.costs??3500}"></label></div><p id="project-budget-result" aria-live="polite"></p></details><section class="project-steps self-review"><h3>Je relis mon travail</h3>${t.review.map((task,i)=>`<label><input type="checkbox" name="review-${i}" ${p.review?.[i]?'checked':''}><span>${esc(task)}</span></label>`).join('')}</section><label class="field">Mon prochain petit pas<textarea name="nextStep" rows="2" maxlength="2000">${esc(p.nextStep||'')}</textarea></label><div class="modal-actions"><button class="primary" type="submit">Enregistrer sur cet appareil ✓</button><button class="secondary" type="button" data-export-project="${id}">Exporter ma fiche</button></div><p class="profile-line" id="project-save-status">${p.updatedAt?'Dernière sauvegarde : '+esc(p.updatedAt.slice(0,10)):''}</p></form><details class="project-course-links"><summary>Les cours pour m’aider</summary>${t.courses.map(id=>`<button class="secondary" data-school-course="${id}">${esc(getCourse(id).title)} →</button>`).join('')}</details><p class="profile-line">Brouillon original Nunya · à faire relire. Utilise des exemples fictifs ; n’inscris pas d’identité, de donnée de patient ou de code secret. Rien n’est envoyé automatiquement.</p>`,true);projectBudgetPreview()}catch{toast('Le projet n’est pas encore disponible sur cet appareil. Ouvre-le une première fois avec une connexion.')}}
function normalizeProjectBudget(raw){const bounded=(v,max)=>Number.isFinite(Number(v))?Math.max(0,Math.min(max,Number(v))):0;const quantity=Math.floor(bounded(raw.quantity,100000)),price=bounded(raw.price,100000000),costs=bounded(raw.costs,100000000);return {quantity,price,costs,revenue:quantity*price,result:quantity*price-costs}}
function projectBudgetPreview(){if(!$('#project-budget-result'))return;const b=normalizeProjectBudget({quantity:$('#project-quantity').value,price:$('#project-price').value,costs:$('#project-costs').value});$('#project-budget-result').textContent=`Recettes fictives : ${b.revenue.toLocaleString('fr-FR')} FCFA · Résultat simplifié : ${b.result.toLocaleString('fr-FR')} FCFA.`}

function saveProjectForm(){if(!currentProject)return;const form=$('#local-project-form');if(!form.reportValidity())return;const f=new FormData(form),num=(key,max)=>Math.max(0,Math.min(max,Number(f.get(key))||0));state.localProjects[currentProject.id]={title:String(f.get('title')).slice(0,100),idea:String(f.get('idea')).slice(0,3000),observations:String(f.get('observations')).slice(0,3000),nextStep:String(f.get('nextStep')).slice(0,2000),tasks:currentProject.tasks.map((_,i)=>f.has('task-'+i)),review:currentProject.review.map((_,i)=>f.has('review-'+i)),budget:normalizeProjectBudget({quantity:num('quantity',100000),price:num('price',100000000),costs:num('costs',100000000)}),updatedAt:new Date().toISOString(),selfAssessed:true};persist();$('#project-save-status').textContent='Enregistré sur cet appareil · '+new Date().toLocaleTimeString('fr-FR');toast('Ton projet est enregistré. Retrouve-le dans Ma progression.');return state.localProjects[currentProject.id]}
function restoreLocalProjects(data){if(!data||typeof data!=='object'||Array.isArray(data))return;for(const [id,p]of Object.entries(data).slice(0,13)){if(!SECTORS.some(s=>s.id===id)||!p||typeof p!=='object')continue;state.localProjects[id]={title:String(p.title||'Projet').slice(0,100),idea:String(p.idea||'').slice(0,3000),observations:String(p.observations||'').slice(0,3000),nextStep:String(p.nextStep||'').slice(0,2000),tasks:Array.isArray(p.tasks)?p.tasks.slice(0,3).map(Boolean):[],review:Array.isArray(p.review)?p.review.slice(0,4).map(Boolean):[],budget:{quantity:Math.max(0,Math.min(100000,Number(p.budget?.quantity)||0)),price:Math.max(0,Math.min(100000000,Number(p.budget?.price)||0)),costs:Math.max(0,Math.min(100000000,Number(p.budget?.costs)||0))},updatedAt:typeof p.updatedAt==='string'?p.updatedAt.slice(0,30):new Date().toISOString(),selfAssessed:true}}}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.localProject){e.stopImmediatePropagation();openProject(b.dataset.localProject)}else if(b.dataset.exportProject){e.stopImmediatePropagation();const p=saveProjectForm();if(p)downloadJSON({format:'nunya-project-v1',projectId:currentProject.id,template:currentProject,work:p},'nunya-projet-'+currentProject.id+'.json')}},true);
document.addEventListener('submit',e=>{if(e.target.id==='local-project-form'){e.preventDefault();e.stopImmediatePropagation();saveProjectForm()}},true);
document.addEventListener('input',e=>{if(e.target.closest('.project-budget'))projectBudgetPreview()});
loadProjects().then(()=>{if(['home','progress','careers'].includes(page)&&$('#modal').hidden)render()}).catch(()=>{});
